\"\"\"Private OpenAI Responses API client using only the Python standard library.

Sends text prompts to https://api.openai.com/v1/responses and returns the
model's output. The API key is read from the OPENAI_API_KEY environment
variable so secrets are never hardcoded into source.
\"\"\"

import json
import os
import urllib.error
import urllib.request
import sys

RESPONSES_ENDPOINT = \"https://api.openai.com/v1/responses\"


class OpenAIResponseError(RuntimeError):
    \"\"\"Raised when the Responses API returns an error or the request fails.\"\"\"


def send_prompt(text, model=\"gpt-4o\", api_key=None,
                max_output_tokens=None, temperature=None):
    \"\"\"Send a single private text prompt to the OpenAI Responses API.

    Args:
        text: The prompt text to send.
        model: Model identifier, e.g. \"gpt-4o\".
        api_key: API key; falls back to the OPENAI_API_KEY env variable.
        max_output_tokens: Optional cap on generated tokens.
        temperature: Optional sampling temperature.

    Returns:
        The concatenated text content of the model's response.
    \"\"\"
    api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
    if not api_key:
        raise OpenAIResponseError(
            \"No API key provided. Set OPENAI_API_KEY or pass api_key.\"
        )

    payload = {\"model\": model, \"input\": text}
    if max_output_tokens is not None:
        payload[\"max_output_tokens\"] = max_output_tokens
    if temperature is not None:
        payload[\"temperature\"] = temperature

    data = json.dumps(payload).encode(\"utf-8\")
    request = urllib.request.Request(
        RESPONSES_ENDPOINT,
        data=data,
        headers={
            \"Authorization\": \"Bearer \" + api_key,
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )

    try:
        with urllib.request.urlopen(request) as response:
            body = response.read().decode(\"utf-8\")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode(\"utf-8\", errors=\"replace\")
        raise OpenAIResponseError(
            \"HTTP %s from Responses API: %s\" % (exc.code, detail)
        ) from exc
    except urllib.error.URLError as exc:
        raise OpenAIResponseError(\"Network error: %s\" % exc.reason) from exc

    parsed = json.loads(body)
    if \"error\" in parsed:
        raise OpenAIResponseError(str(parsed[\"error\"]))

    return _extract_text(parsed)


def _extract_text(parsed):
    \"\"\"Pull concatenated text output from a Responses API payload.\"\"\"
    parts = []
    for item in parsed.get(\"output\", []):
        for content in item.get(\"content\", []):
            if content.get(\"type\") == \"output_text\":
                parts.append(content.get(\"text\", \"\"))
    return \"\".join(parts)


def main(argv):
    if len(argv) < 2:
        print('usage: python openai_client.py \"your prompt\"', file=sys.stderr)
        return 2
    prompt = argv[1]
    try:
        print(send_prompt(prompt))
    except OpenAIResponseError as exc:
        print(\"error: %s\" % exc, file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    sys.exit(main(sys.argv))
PYEOF
